from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(7,'pourcentages','Proportions et pourcentages','2 · Modéliser et mesurer',
'Centièmes · Proportions · Appliquer un pourcentage',
['Donner du sens à une écriture en pourcentage.','Exprimer une proportion simple sous forme de fraction, de décimal ou de pourcentage.','Appliquer un pourcentage à un nombre ou à une grandeur.'],
['Fractions décimales ; fraction d’un nombre ; multiplication par un entier.'],[
page(1,'La référence à cent',
bloc('definition',r'Un pourcentage est une fraction de dénominateur 100 : 35~% $=\frac{35}{100}=0{,}35$. « 35 pour cent » signifie 35 sur 100 : 35 parts d’un tout partagé en 100 parts égales.'),
r'@FIG:cours-grille-100@',
sec(2,'Relier fraction, décimal et pourcentage'),
bloc('propriete',r'Pourcentages à connaître : 100~% représente le tout ; 50~% $=\frac12=0{,}5$ ; 25~% $=\frac14=0{,}25$ ; 75~% $=\frac34=0{,}75$ ; 10~% $=\frac1{10}=0{,}1$ ; 20~% $=\frac15=0{,}2$.'),
bloc('savoirfaire',r'Pour écrire $\frac35$ en pourcentage, on cherche une fraction égale de dénominateur 100 : $\frac35=\frac{60}{100}=60$~%. Inversement, 8~% $=\frac8{100}=0{,}08$.','Changer d’écriture')),
page(3,'Exprimer une proportion simple',
bloc('definition',r'La proportion d’une partie dans un tout est le quotient de la partie par le tout. Sur 25 élèves, 9 portent des lunettes : la proportion est $\frac9{25}=\frac{36}{100}$, soit 36~%.'),
bloc('savoirfaire',r'Quand le tout est un diviseur de 100 (2, 4, 5, 10, 20, 25, 50) ou un multiple de 100, on obtient facilement un dénominateur 100 : $\frac7{20}=\frac{35}{100}=35$~% ; $\frac{12}{200}=\frac6{100}=6$~%.','Se ramener à cent'),
sec(4,'Appliquer un pourcentage'),
bloc('savoirfaire',r'Prendre 30~% de 80, c’est calculer $\frac{30}{100}\times80=24$. On peut aussi passer par 10~% : 10~% de 80 vaut 8, donc 30~% de 80 vaut $3\times8=24$.','Calculer un pourcentage d’un nombre'),
r'@FIG:cours-bande-pct@',
bloc('attention',r'Un pourcentage se rapporte toujours à un tout : 50~% de 20 € et 50~% de 200 € ne sont pas la même somme. Une partie d’un tout représente au plus 100~% de ce tout.')),
],[
E('Lire une grille',r'La grille compte 100 cases. Quelle proportion de la grille est colorée ? L’écrire sous forme de fraction, d’écriture décimale et de pourcentage.',r'42 cases sur 100 : $\res{\frac{42}{100}}=\res{0{,}42}=\res{42\text{~\%}}$.','Compter les cases sur cent.','assert Rational(42,100)==Rational(".42")',figure='pct-1'),
E('Trois écritures',r'Recopier et compléter le tableau.'+tableau(['Fraction','Écriture décimale','Pourcentage'],[[r'$\frac34$','…','…'],['…',r'$0{,}1$','…'],['…','…','60 %'],[r'$\frac15$','…','…']]),r'$\frac34=\res{0{,}75}=\res{75\text{~\%}}$ ; $0{,}1=\res{\frac1{10}}=\res{10\text{~\%}}$ ; 60~% $=\res{\frac35}=\res{0{,}6}$ ; $\frac15=\res{0{,}2}=\res{20\text{~\%}}$.','Passer par une fraction de dénominateur 100.','assert Rational(3,4)==Rational(".75")==Rational(75,100) and Rational(1,10)==Rational(10,100) and Rational(60,100)==Rational(3,5)==Rational(".6") and Rational(1,5)==Rational(20,100)'),
E('Pourcentages usuels',r'Calculer de tête : 50~% de 46 ; 25~% de 80 ; 10~% de 350 ; 75~% de 12.',r'La moitié de 46 : $\res{23}$. Le quart de 80 : $\res{20}$. Le dixième de 350 : $\res{35}$. Trois quarts de 12 : $\res9$.','Associer chaque pourcentage à une fraction simple.','assert Rational(50,100)*46==23 and Rational(25,100)*80==20 and Rational(10,100)*350==35 and Rational(75,100)*12==9'),
E('Une proportion',r'Dans une classe de 25 élèves, 9 portent des lunettes. Quelle est la proportion d’élèves qui portent des lunettes ? L’écrire en pourcentage.',r'$\frac9{25}=\frac{9\times4}{25\times4}=\frac{36}{100}$ : $\res{36\text{~\%}}$ des élèves.','Partie sur tout, puis dénominateur 100.','assert Rational(9,25)==Rational(36,100)'),
E('Partie d’un tout',r'Un sac contient 200 billes ; 30~% d’entre elles sont rouges. Combien y a-t-il de billes rouges ?',r'$\frac{30}{100}\times200=\res{60}$ billes rouges : 30 billes pour chaque centaine.','Appliquer le pourcentage au tout.','assert Rational(30,100)*200==60'),
E('Des proportions simples',r'Exprimer en pourcentage : 7 sur 20 ; 12 sur 50 ; 3 sur 4 ; 45 sur 300.',r'$\frac7{20}=\frac{35}{100}$ : $\res{35\text{~\%}}$. $\frac{12}{50}=\frac{24}{100}$ : $\res{24\text{~\%}}$. $\frac34$ : $\res{75\text{~\%}}$. $\frac{45}{300}=\frac{15}{100}$ : $\res{15\text{~\%}}$.','Multiplier ou diviser pour obtenir un dénominateur 100.','assert Rational(7,20)==Rational(35,100) and Rational(12,50)==Rational(24,100) and Rational(3,4)==Rational(75,100) and Rational(45,300)==Rational(15,100)'),
E('Appliquer à une grandeur',r'Calculer : 20~% de $3{,}5$ kg ; 15~% de 60 min ; 5~% de 240 €.',r'$\frac15\times3{,}5=\res{0{,}7\ \mathrm{kg}}$. $\frac{15}{100}\times60=\res{9\ \mathrm{min}}$. 10~% de 240 vaut 24, donc 5~% vaut $\res{12}$ €.','Garder l’unité de la grandeur.','assert Rational(20,100)*Rational("3.5")==Rational(".7") and Rational(15,100)*60==9 and Rational(5,100)*240==12'),
E('Les trajets du matin',r'La bande représente les 240 élèves d’un collège selon leur moyen de transport. Quel pourcentage vient à pied ? Combien d’élèves cela représente-t-il dans chaque catégorie ?',r'À pied : $100-45-30=\res{25\text{~\%}}$. Bus : $\frac{45}{100}\times240=\res{108}$ élèves ; vélo : $\res{72}$ ; à pied : $\res{60}$. Contrôle : $108+72+60=240$.','Le tout représente 100 %.','assert 100-45-30==25 and Rational(45,100)*240==108 and Rational(30,100)*240==72 and Rational(25,100)*240==60',figure='pct-8'),
E('Comparer des proportions',r'Dans la classe A, il y a 18 filles sur 30 élèves ; dans la classe B, 13 filles sur 25 élèves. Dans quelle classe la proportion de filles est-elle la plus grande ?',r'A : $\frac{18}{30}=\frac35=\frac{60}{100}$, soit 60~%. B : $\frac{13}{25}=\frac{52}{100}$, soit 52~%. La proportion est plus grande dans la $\res{\text{classe A}}$, même si les effectifs diffèrent.','Comparer des pourcentages plutôt que des effectifs.','assert Rational(18,30)==Rational(60,100) and Rational(13,25)==Rational(52,100) and Rational(18,30)>Rational(13,25)'),
E('Le pourcentage manquant',r'Lors d’un sondage auprès de 500 personnes, 46~% ont répondu oui et 38~% non ; les autres sont sans avis. Quel pourcentage est sans avis ? Combien de personnes cela fait-il ?',r'Sans avis : $100-46-38=\res{16\text{~\%}}$. Nombre : $\frac{16}{100}\times500=\res{80}$ personnes.','Compléter à 100 %, puis appliquer.','assert 100-46-38==16 and Rational(16,100)*500==80'),
E('Les soldes',r'Un jean coûte 60 €. Pendant les soldes, son prix baisse de 30~%. Calculer la réduction, puis le nouveau prix.',r'Réduction : $\frac{30}{100}\times60=\res{18}$ €. Nouveau prix : $60-18=\res{42}$ €.','Calculer la réduction avant de la retrancher.','assert Rational(30,100)*60==18 and 60-18==42'),
E('Le jus de fruits',r'Une brique de $1{,}5$ L de boisson contient 12~% de jus de pomme. Quel volume de jus de pomme contient-elle ? Répondre en litres, puis en centilitres.',r'10~% de $1{,}5$ L valent $0{,}15$ L et 2~% valent $0{,}03$ L : 12~% valent $\res{0{,}18\ \mathrm{L}}$, soit $\res{18\ \mathrm{cL}}$.','Décomposer 12 % en 10 % plus 2 %.','assert Rational(12,100)*Rational("1.5")==Rational(".18") and Rational(".18")*100==18'),
E('La commune et sa forêt',r'Une commune s’étend sur $2\,400$ hectares : 35~% sont couverts de forêt, 40~% de champs, et le reste par des habitations et des routes. Calculer la surface de chaque partie.',r'Forêt : $\frac{35}{100}\times2\,400=\res{840}$ ha. Champs : $\res{960}$ ha. Reste : $100-35-40=25$~%, soit $\res{600}$ ha. Contrôle : $840+960+600=2\,400$.','Appliquer chaque pourcentage au même tout.','assert Rational(35,100)*2400==840 and Rational(40,100)*2400==960 and Rational(25,100)*2400==600 and 840+960+600==2400'),
E('L’élection des délégués',r'Dans une classe, 28 élèves ont voté : Inès a obtenu 14 voix, Jules 7 voix et Sami 7 voix. Exprimer le résultat de chaque candidat en pourcentage.',r'Inès : $\frac{14}{28}=\frac12$, soit $\res{50\text{~\%}}$. Jules et Sami : $\frac7{28}=\frac14$, soit $\res{25\text{~\%}}$ chacun.','Simplifier la proportion avant de la convertir.','assert Rational(14,28)==Rational(50,100) and Rational(7,28)==Rational(25,100)'),
E('Vrai ou faux',r'Maël affirme : « 20~% de 50, c’est la même chose que 50~% de 20. » Vérifier par le calcul, puis expliquer.',r'20~% de 50 : $\frac{20}{100}\times50=10$. 50~% de 20 : la moitié de 20, soit 10. C’est $\res{\text{vrai}}$ : dans les deux cas, on calcule $\frac{20\times50}{100}$.','Écrire chaque calcul avec une fraction.','assert Rational(20,100)*50==Rational(50,100)*20==10')
],reperes=['Sens d’un pourcentage','Fraction, décimal et pourcentage','Proportion d’une partie dans un tout','Appliquer un pourcentage'],deco='statistiques')

chapitre(8,'prealgebre','Chercher des inconnues et des régularités','2 · Modéliser et mesurer',
'Quantités inconnues · Schémas en barres · Motifs évolutifs',
['Traduire les relations entre des quantités inconnues.','Représenter un problème par un schéma en barres pour le résoudre.','Repérer la structure d’un motif évolutif et prévoir une étape lointaine.'],
['Sens des quatre opérations ; programmes de calcul du CM2.'],[
page(1,'Décrire une quantité inconnue',
bloc('definition',r'Une quantité inconnue est un nombre que l’on ne connaît pas encore, mais qui obéit à des relations : « 3 fois plus que », « 15 de plus que », « ensemble, ils font 48 ». On peut la décrire avec des mots, un dessin ou une barre.'),
bloc('exemple',r'« Léo a 3 fois plus de billes que Mia ; ensemble, ils en ont 48. » On ne connaît aucun des deux nombres, mais on connaît les relations qui les lient.'),
sec(2,'Représenter les relations par des barres'),
bloc('savoirfaire',r'On dessine une barre par quantité, avec des longueurs cohérentes : Mia, une barre ; Léo, trois barres identiques. Les quatre barres valent 48, donc une barre vaut $48:4=12$. Mia a 12 billes et Léo $3\times12=36$.','Schéma en barres'),
r'@FIG:cours-barres@',
bloc('propriete',r'Somme et écart : deux nombres ont pour somme 50 et pour écart 14. On retire l’écart : il reste $50-14=36$ pour deux barres égales. Le petit nombre vaut $36:2=18$, le grand $18+14=32$.')),
page(3,'Raisonner sans connaître tous les nombres',
bloc('savoirfaire',r'« Je pense à un nombre, je le multiplie par 4, j’ajoute 7 et j’obtiens 39. » On défait les étapes dans l’ordre inverse : $39-7=32$, puis $32:4=8$. Contrôle : $8\times4+7=39$.','Remonter les étapes'),
bloc('attention',r'On vérifie toujours que les nombres trouvés respectent toutes les conditions de l’énoncé, et pas seulement la dernière.'),
sec(4,'Comprendre un motif évolutif'),
bloc('definition',r'Un motif évolutif change d’une étape à la suivante selon une règle. Pour comprendre sa structure, on repère ce qui reste fixe et ce qui s’ajoute à chaque étape.'),
r'@FIG:cours-motif@',
bloc('savoirfaire',r'Ici, il y a une allumette de départ, puis 3 allumettes par carré. À l’étape 10 : $1+3\times10=31$ allumettes ; à l’étape 100 : $1+3\times100=301$. On peut l’écrire : nombre d’allumettes $=1+3\times$ numéro de l’étape.','Prévoir une étape lointaine')),
],[
E('Traduire par des barres',r'Marc a 15 € de plus que Lina. Ensemble, ils ont 75 €. Compléter le schéma en barres, puis trouver la somme de chacun.',r'On retire les 15 € d’écart : $75-15=60$ € pour deux barres égales. Lina a $\res{30}$ € et Marc $30+15=\res{45}$ €. Contrôle : $30+45=75$.','Retirer l’écart, puis partager.','assert (75-15)//2==30 and 30+15==45 and 30+45==75',figure='alg-1'),
E('Quatre fois plus',r'Un livre et un cahier coûtent ensemble 20 €. Le livre coûte 4 fois plus cher que le cahier. Trouver le prix de chacun.',r'Cahier : 1 barre ; livre : 4 barres. Cinq barres valent 20 € : une barre vaut 4 €. Cahier : $\res4$ € ; livre : $\res{16}$ €.','Compter les barres identiques.','assert 20//5==4 and 4*4==16 and 4+16==20'),
E('Poursuivre un motif',r'Voici les trois premières étapes d’un motif d’allumettes. Combien d’allumettes faut-il pour l’étape 4 ? Pour l’étape 5 ?',r'On passe de 4 à 7, puis à 10 : on ajoute 3 allumettes par carré. Étape 4 : $\res{13}$ ; étape 5 : $\res{16}$.','Repérer ce qui s’ajoute à chaque étape.','L=[1+3*k for k in range(1,6)]\nassert L==[4,7,10,13,16]',figure='alg-3'),
E('Le nombre pensé',r'Je pense à un nombre. Je le multiplie par 4, puis j’ajoute 7. J’obtiens 39. Quel est mon nombre ?',r'On remonte : $39-7=32$, puis $32:4=\res8$. Contrôle : $8\times4+7=39$.','Défaire les étapes dans l’ordre inverse.','assert (39-7)//4==8 and 8*4+7==39'),
E('Égalité de barres',r'Sur le schéma, trois barres identiques et un morceau de 5 forment la même longueur qu’une barre de 26. Que vaut une barre identique ?',r'Les trois barres valent $26-5=21$, donc une barre vaut $21:3=\res7$. Contrôle : $3\times7+5=26$.','Enlever la partie connue, puis partager.','assert (26-5)//3==7 and 3*7+5==26',figure='alg-5'),
E('Somme et écart',r'Deux nombres ont pour somme 50 et pour écart 14. Trouver ces deux nombres.',r'Deux barres égales valent $50-14=36$ : le petit nombre est $\res{18}$, le grand $\res{32}$. Contrôles : $18+32=50$ et $32-18=14$.','Égaliser les barres en retirant l’écart.','assert 18+32==50 and 32-18==14'),
E('Partage inégal',r'Trois amis se partagent 96 cartes. Ali en a le double de Bo, et Cléa en a autant qu’Ali et Bo réunis. Combien de cartes chacun a-t-il ?',r'Bo : 1 barre ; Ali : 2 barres ; Cléa : 3 barres. Six barres valent 96 : une barre vaut 16. Bo $\res{16}$, Ali $\res{32}$, Cléa $\res{48}$.','Exprimer chaque part en barres de Bo.','assert 96//6==16 and 16+32+48==96 and 48==16+32'),
E('Le motif en L',r'Voici trois étapes d’un motif en forme de L. Combien de carreaux à l’étape 10 ? À quelle étape le motif compte-t-il 41 carreaux ?',r'Étape 1 : 3 carreaux ; on ajoute 2 carreaux à chaque étape, un par branche. Étape 10 : $1+2\times10=\res{21}$. Pour 41 carreaux : $41-1=40$ et $40:2=$ étape $\res{20}$.','Un carreau d’angle, puis deux carreaux par étape.','assert [1+2*k for k in (1,2,3)]==[3,5,7] and 1+2*10==21 and (41-1)//2==20',figure='alg-8'),
E('L’étape 100',r'Pour le motif d’allumettes du cours (4, 7, 10…), combien faut-il d’allumettes pour l’étape 100 ? Décrire la règle avec une phrase.',r'Une allumette de départ, puis 3 par carré : $1+3\times100=\res{301}$ allumettes. Règle : « le nombre d’allumettes vaut 1 plus 3 fois le numéro de l’étape ».','Décrire la structure plutôt que tout dessiner.','assert 1+3*100==301'),
E('Les âges',r'Aujourd’hui, Paul a 3 fois l’âge de sa fille et la somme de leurs âges est 48 ans. Quel âge a chacun ? Dans combien d’années Paul aura-t-il exactement le double de l’âge de sa fille ?',r'Quatre barres valent 48 : la fille a $\res{12}$ ans et Paul $\res{36}$ ans. L’écart, 24 ans, ne change jamais. Paul a le double quand la fille a 24 ans : dans $\res{12}$ ans (Paul aura 48 ans).','L’écart d’âge reste constant.','assert 48//4==12 and 3*12==36 and 36+12==48 and 36+12==2*(12+12)'),
E('Les places de cinéma',r'Deux adultes et trois enfants paient 41 € au cinéma. Une place adulte coûte 3 € de plus qu’une place enfant. Trouver le prix de chaque place.',r'Si les adultes payaient le tarif enfant, on paierait $41-2\times3=35$ € pour 5 places : la place enfant coûte $\res7$ €, la place adulte $\res{10}$ €. Contrôle : $2\times10+3\times7=41$.','Ramener toutes les barres à la même taille.','assert (41-2*3)//5==7 and 2*10+3*7==41'),
E('L’escalier de cubes',r'On construit des escaliers de cubes : 1 cube à l’étape 1, 3 cubes à l’étape 2, 6 cubes à l’étape 3. Combien de cubes à l’étape 6 ? À l’étape 10 ?',r'À l’étape $n$, on ajoute une colonne de $n$ cubes. Étape 4 : 10 ; étape 5 : 15 ; étape 6 : $\res{21}$. Étape 10 : $1+2+\ldots+10=\res{55}$.','Repérer ce qui s’ajoute : de plus en plus de cubes.','assert sum(range(1,4))==6 and sum(range(1,7))==21 and sum(range(1,11))==55',figure='alg-12'),
E('La croix qui grandit',r'Une croix compte 5 carreaux à l’étape 1, 9 à l’étape 2 et 13 à l’étape 3. À quelle étape compte-t-elle 101 carreaux ?',r'Un carreau central et 4 carreaux de plus à chaque étape : $1+4\times$ numéro. $101-1=100$ et $100:4=25$ : étape $\res{25}$.','Retirer la partie fixe, puis diviser.','assert [1+4*k for k in (1,2,3)]==[5,9,13] and 1+4*25==101',figure='alg-13'),
E('Les deux réservoirs',r'Le réservoir A contient 3 fois plus d’eau que le réservoir B. On verse 20 L de A dans B : les deux réservoirs contiennent alors la même quantité. Combien chaque réservoir contenait-il au départ ?',r'A : 3 barres ; B : 1 barre ; écart : 2 barres. Après le transfert, l’écart est nul : 2 barres valent $2\times20=40$ L. Une barre vaut 20 L : B contenait $\res{20}$ L et A $\res{60}$ L. Contrôle : $60-20=20+20$.','Le transfert réduit l’écart de deux fois 20 L.','assert 3*20-20==20+20'),
E('Vrai ou faux',r'Nour affirme : « Dans le motif 4, 7, 10…, l’étape 10 contient 10 fois plus d’allumettes que l’étape 1. » A-t-elle raison ?',r'Étape 1 : 4 allumettes ; étape 10 : 31, et non $10\times4=40$. C’est $\res{\text{faux}}$ : l’allumette de départ n’est comptée qu’une fois.','Comparer avec la règle du motif.','assert 1+3*10==31 and 31!=10*4')
],reperes=['Décrire des quantités inconnues','Schémas en barres','Raisonner sans connaître tous les nombres','Motifs évolutifs'],deco='suites')

chapitre(9,'proportionnalite','Proportionnalité et échelles','2 · Modéliser et mesurer',
'Grandeurs · Linéarité · Retour à l’unité · Échelles',
['Reconnaître une situation de proportionnalité entre deux grandeurs.','Choisir une procédure adaptée : fois plus, sommes, retour à l’unité.','Représenter une situation dans un tableau et utiliser une échelle.'],
['Multiplication et division ; « fois plus, fois moins » du cours moyen.'],[
page(1,'Reconnaître une situation proportionnelle',
bloc('definition',r'Deux grandeurs sont proportionnelles lorsque, si l’on multiplie (ou divise) une mesure de l’une par un nombre, la mesure correspondante de l’autre est multipliée (ou divisée) par le même nombre. Exemple : la masse de pommes achetées et le prix payé, à $2{,}50$ € le kilogramme.'),
bloc('propriete',r'Dans une situation de proportionnalité, une grandeur « par unité » reste constante : le prix au kilogramme, le nombre de battements du cœur par minute, la quantité de farine par personne.'),
bloc('attention',r'Toutes les situations ne sont pas proportionnelles : la taille d’un enfant ne double pas quand son âge double ; une course de taxi avec une prise en charge ne coûte pas deux fois plus cher pour deux fois plus de kilomètres.'),
sec(2,'Utiliser les relations entre les mesures'),
bloc('savoirfaire',r'4 croissants coûtent $3{,}60$ €. 12 croissants, c’est 3 fois plus : ils coûtent 3 fois plus, $10{,}80$ €. 2 croissants, c’est 2 fois moins : $1{,}80$ €.','Fois plus, fois moins'),
bloc('savoirfaire',r'2 kg de farine coûtent $3{,}20$ € et 3 kg coûtent $4{,}80$ €. Donc 5 kg, soit 2 kg et 3 kg, coûtent $3{,}20+4{,}80=8$ €.','Additionner deux situations')),
page(3,'Revenir à l’unité et représenter',
bloc('savoirfaire',r'5 cahiers coûtent $7{,}50$ €. Un cahier coûte $7{,}50:5=1{,}50$ € ; 8 cahiers coûtent donc $8\times1{,}50=12$ €.','Retour à l’unité'),
r'@FIG:cours-tableau-fleches@',
bloc('exemple',r'Dans un tableau, on écrit le nom de chaque grandeur et son unité. On peut aussi noter : prix(2 kg) $=5$ € ; prix(6 kg) $=3\times$ prix(2 kg) $=15$ €.'),
sec(4,'Lire et utiliser une échelle'),
bloc('definition',r'Sur un plan à l’échelle, les longueurs du plan et les longueurs réelles sont proportionnelles. « 1 cm pour 50 m » signifie que 1 cm sur le plan représente 50 m en réalité.'),
r'@FIG:cours-echelle@',
bloc('savoirfaire',r'6,5 cm sur le plan représentent $6{,}5\times50=325$ m. Une distance réelle de 400 m mesure $400:50=8$ cm sur le plan.','Du plan à la réalité')),
],[
E('Proportionnel ou pas ?',r'Dire si les deux grandeurs sont proportionnelles, en justifiant.'+Q(r'Le prix payé et le nombre de baguettes achetées, à $1{,}20$ € la baguette.',r'La taille d’un enfant et son âge.',r'Le périmètre d’un carré et la longueur de son côté.',r'Le prix d’une course de taxi (4 € de prise en charge et 2 € par kilomètre) et la distance parcourue.'),r'1. $\res{\text{Oui}}$ : le prix par baguette est constant. 2. $\res{\text{Non}}$ : à 20 ans, on ne mesure pas deux fois sa taille de 10 ans. 3. $\res{\text{Oui}}$ : le périmètre vaut 4 fois le côté. 4. $\res{\text{Non}}$ : 5 km coûtent 14 € mais 10 km coûtent 24 €, et non 28 €.','Chercher une grandeur par unité constante.','assert 4+2*5==14 and 4+2*10==24 and 24!=2*14'),
E('Trois fois plus',r'4 croissants coûtent $3{,}60$ €. Combien coûtent 12 croissants ? Et 2 croissants ?',r'12, c’est 3 fois 4 : $3\times3{,}60=\res{10{,}80}$ €. 2, c’est 2 fois moins que 4 : $3{,}60:2=\res{1{,}80}$ €.','Multiplier ou diviser les deux grandeurs par le même nombre.','assert 3*Rational("3.6")==Rational("10.8") and Rational("3.6")/2==Rational("1.8")'),
E('Retour à l’unité',r'5 cahiers identiques coûtent $7{,}50$ €. Combien coûtent 8 cahiers ?',r'Un cahier : $7{,}50:5=1{,}50$ €. Huit cahiers : $8\times1{,}50=\res{12}$ €.','Calculer le prix d’un cahier.','assert Rational("7.5")/5==Rational("1.5") and 8*Rational("1.5")==12'),
E('Additionner des situations',r'2 kg de farine coûtent $3{,}20$ € et 3 kg coûtent $4{,}80$ €. Combien coûtent 5 kg ? Et 1 kg ?',r'5 kg $=$ 2 kg $+$ 3 kg : $3{,}20+4{,}80=\res8$ €. 1 kg $=$ 3 kg $-$ 2 kg : $4{,}80-3{,}20=\res{1{,}60}$ €.','Ajouter ou retrancher deux situations connues.','assert Rational("3.2")+Rational("4.8")==8 and Rational("4.8")-Rational("3.2")==Rational("1.6")'),
E('Lire une échelle',r'Sur le plan, 1 cm représente 200 m. La distance entre l’école et le gymnase mesure 4 cm sur le plan. Quelle est la distance réelle ?',r'4 cm, c’est 4 fois 1 cm : $4\times200=\res{800}$ m.','Multiplier la longueur du plan par la valeur d’un centimètre.','assert 4*200==800',figure='pro-5'),
E('Compléter un tableau',r'Le prix d’un fromage est proportionnel à sa masse. Recopier et compléter le tableau.'+tableau(['Masse (kg)','2','3','5','10'],[['Prix (€)','7','…','…','…']]),r'Prix au kilogramme : $7:2=3{,}50$ €. 3 kg : $\res{10{,}50}$ € ; 5 kg : $\res{17{,}50}$ € ; 10 kg : $\res{35}$ €, cinq fois le prix de 2 kg.','Revenir au prix d’un kilogramme.','assert Rational(7,2)*3==Rational("10.5") and Rational(7,2)*5==Rational("17.5") and 7*5==35'),
E('Les battements du cœur',r'Au repos, le cœur de Sam bat régulièrement 72 fois par minute. Combien de battements en 5 minutes ? En 30 secondes ? En une heure ?',r'5 min : $5\times72=\res{360}$. 30 s : deux fois moins qu’en une minute, $\res{36}$. 1 h $=60$ min : $60\times72=\res{4\,320}$ battements.','Utiliser le nombre de battements par minute.','assert 5*72==360 and 72//2==36 and 60*72==4320'),
E('Proportionnel ?',r'Un parc d’attractions affiche ses tarifs. Le prix est-il proportionnel au nombre de places ?'+tableau(['Nombre de places','1','2','3','4'],[['Prix (€)','8','16','24','30']]),r'Si c’était proportionnel, 4 places coûteraient $4\times8=32$ €. Or elles coûtent 30 € : $\res{\text{non}}$, ce n’est pas proportionnel (une réduction s’applique à partir de 4 places).','Tester chaque colonne avec le prix d’une place.','assert 4*8==32 and 32!=30 and 2*8==16 and 3*8==24'),
E('Le plan du jardin',r'Sur ce plan, 1 cm représente 2 m. Le jardin est représenté par un rectangle de 6 cm sur $4{,}5$ cm. Quelles sont ses dimensions réelles ?',r'$6\times2=\res{12}$ m et $4{,}5\times2=\res9$ m : le jardin mesure 12 m sur 9 m.','Multiplier chaque longueur par 2 m.','assert 6*2==12 and Rational("4.5")*2==9',figure='pro-9'),
E('La recette',r'Pour 6 personnes, une recette demande 300 g de farine, 3 œufs et $0{,}6$ L de lait. Adapter la recette pour 4 personnes.',r'On revient à 2 personnes (3 fois moins), puis on double : farine $\res{200\ \mathrm{g}}$, $\res{2}$ œufs, lait $\res{0{,}4\ \mathrm{L}}$.','Passer par un nombre de personnes commode.','assert 300//3*2==200 and 3//3*2==2 and Rational(".6")/3*2==Rational(".4")'),
E('La carte de randonnée',r'Sur la carte, 1 cm représente 250 m. Le chemin suivi est formé de trois portions de 2 cm, $3{,}4$ cm et $1{,}6$ cm. Quelle distance réelle parcourt-on ?',r'Sur la carte : $2+3{,}4+1{,}6=7$ cm. En réalité : $7\times250=\res{1\,750}$ m, soit $1{,}75$ km.','Additionner sur la carte, puis convertir une seule fois.','assert 2+Rational("3.4")+Rational("1.6")==7 and 7*250==1750',figure='pro-11'),
E('Le robinet',r'Un robinet débite régulièrement 12 L d’eau en $1{,}5$ min. Quelle quantité en 6 min ? En 1 min ? Combien de temps faut-il pour remplir une cuve de 100 L ?',r'6 min, c’est 4 fois $1{,}5$ min : $\res{48}$ L. En 1 min : $12:1{,}5=\res8$ L. 100 L : $100:8=\res{12{,}5}$ min, soit 12 min 30 s.','Choisir entre « fois plus » et retour à l’unité.','assert 4*Rational("1.5")==6 and 4*12==48 and 12/Rational("1.5")==8 and Rational(100,8)==Rational("12.5")'),
E('Le meilleur prix',r'Un paquet de café de 500 g coûte $2{,}40$ € ; un paquet de 750 g coûte $3{,}30$ €. Calculer le prix au kilogramme de chaque paquet. Lequel est le plus avantageux ?',r'500 g, c’est la moitié d’un kilogramme : $2\times2{,}40=\res{4{,}80}$ € le kg. 750 g : 250 g coûtent $1{,}10$ €, donc 1 kg coûte $4\times1{,}10=\res{4{,}40}$ € le kg. Le paquet de $\res{750\ \mathrm{g}}$ est plus avantageux.','Comparer des prix au kilogramme.','assert 2*Rational("2.4")==Rational("4.8") and Rational("3.3")/3*4==Rational("4.4")'),
E('La maquette',r'Sur une maquette d’avion, 1 cm représente 50 cm de l’avion réel. L’envergure de la maquette est de 24 cm : quelle est celle de l’avion ? L’avion mesure 15 m de long : quelle est la longueur de la maquette ?',r'$24\times50=1\,200$ cm, soit $\res{12}$ m. 15 m $=1\,500$ cm et $1\,500:50=\res{30}$ cm.','Travailler dans la même unité.','assert 24*50==1200 and 1500//50==30'),
E('Pas proportionnel !',r'Un taxi facture 4 € de prise en charge, puis 2 € par kilomètre. Calculer le prix d’une course de 5 km, puis de 10 km. Le prix est-il proportionnel à la distance ? Quelle partie du prix l’est ?',r'5 km : $4+10=\res{14}$ €. 10 km : $4+20=\res{24}$ €, et non $2\times14=28$ € : le prix total n’est $\res{\text{pas proportionnel}}$. Seule la partie kilométrique, 2 € par km, est proportionnelle à la distance.','Tester « deux fois plus » sur les deux grandeurs.','assert 4+2*5==14 and 4+2*10==24 and 24!=28')
],reperes=['Reconnaître la proportionnalité','Fois plus, fois moins et sommes','Retour à l’unité et tableaux','Échelles'],deco='grandeurs')
